baseCss:
.aha-numbers{
  container:aha-numbers / inline-size;
  --aha-numbers-surface:var(--aha-white);
  --aha-numbers-ink:var(--aha-text-default);
  --aha-numbers-ink-secondary:var(--aha-text-secondary);
  --aha-numbers-value:var(--aha-color-primary);
  --aha-numbers-divider:var(--aha-border-default);
  background:var(--aha-numbers-surface);
  color:var(--aha-numbers-ink);
  font-family:var(--aha-font-product);
}
.aha-numbers *{box-sizing:border-box}
.aha-numbers--accent{box-shadow:inset 0 0 0 100vmax var(--aha-bg-accent)}
.aha-numbers--accent .aha-numbers__icon{background:var(--aha-white)}
:where(.aha-numbers) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-numbers) :is(ul,ol){list-style:none}
.aha-numbers__inner{--aha-web-gutter:var(--aha-space-64);max-width:var(--aha-breakpoint-desktop);margin:0 auto;padding:var(--aha-space-96) var(--aha-web-gutter)}
.aha-numbers__header{max-width:720px;margin:0 0 var(--aha-space-64)}
.aha-numbers__header--center{margin-inline:auto;text-align:center}
.aha-numbers__title{
  margin:0 0 var(--aha-space-20);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-heading);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-numbers-ink);
}
.aha-numbers__lead{
  max-width:44ch;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-numbers-ink-secondary);
}
.aha-numbers__icon{
  display:flex;align-items:center;justify-content:center;flex:none;
  width:var(--aha-space-48);height:var(--aha-space-48);
  border-radius:var(--aha-radius-default);
  background:var(--aha-bg-accent);color:var(--aha-color-primary);
}
.aha-numbers__cta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);margin-top:var(--aha-space-48)}
.aha-numbers__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-32)}
.aha-numbers__frame{
  overflow:hidden;aspect-ratio:4 / 3;
  border-radius:var(--aha-radius-lg);background:var(--aha-bg-container-secondary);
}
.aha-numbers__image{display:block;width:100%;height:100%;object-fit:cover}
.aha-numbers__stats{display:grid;gap:var(--aha-space-48) var(--aha-space-32)}
.aha-numbers__stat{display:flex;flex-direction:column;gap:var(--aha-space-12)}
.aha-numbers__value{
  font-size:clamp(var(--aha-size-h2),5vw,var(--aha-size-h1));
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-tight);
  color:var(--aha-numbers-value);
}
.aha-numbers__stat-title{
  font-size:var(--aha-size-xl);
  font-weight:var(--aha-weight-semibold);
  line-height:var(--aha-line-height-heading);
  color:var(--aha-numbers-ink);
}
.aha-numbers__stat-text{
  font-size:var(--aha-size-l);
  line-height:var(--aha-line-height-body);
  color:var(--aha-numbers-ink-secondary);
}
.aha-numbers--brand{
  --aha-numbers-surface:var(--aha-vivid-pink-100);
  --aha-numbers-ink:var(--aha-text-inverse);
  --aha-numbers-ink-secondary:var(--aha-text-inverse);
  --aha-numbers-value:var(--aha-text-inverse);
  --aha-numbers-divider:var(--aha-text-inverse);
}
@container aha-numbers (max-width:991px){
  .aha-numbers__title{font-size:var(--aha-size-h3)}
}
@container aha-numbers (max-width:767px){
  .aha-numbers__inner{--aha-web-gutter:var(--aha-space-24);padding:var(--aha-space-48) var(--aha-web-gutter)}
}
@container aha-numbers (max-width:479px){
  .aha-numbers__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter)}
  .aha-numbers__title{font-size:var(--aha-size-h4)}
  .aha-numbers__actions{margin-top:var(--aha-space-24)}
  .aha-numbers__cta{margin-top:var(--aha-space-32)}
}
@container aha-numbers (min-width:768px){
  .aha-numbers--divided .aha-numbers__stats:has(>:first-child:last-child){grid-template-columns:minmax(0,1fr)}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(2):last-child){grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(4):last-child){grid-template-columns:repeat(2,minmax(0,1fr));row-gap:var(--aha-space-32)}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(3n+1):last-child:nth-child(n+7))>:last-child{grid-column:2}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(3n+2):last-child:nth-child(n+5)){grid-template-columns:repeat(6,minmax(0,1fr));row-gap:var(--aha-space-32)}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(3n+2):last-child:nth-child(n+5))>*{grid-column:span 2}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(3n+2):last-child:nth-child(n+5))>:nth-last-child(2){grid-column:2 / span 2}
  .aha-numbers--divided .aha-numbers__stats:has(>:nth-child(3n+2):last-child:nth-child(n+5))>:last-child{grid-column:4 / span 2}
}
@container aha-numbers (min-width:992px){
  .aha-numbers--centred .aha-numbers__stats:has(>:nth-child(3):last-child){grid-template-columns:repeat(3,minmax(0,1fr))}
}

layouts.css:
.aha-numbers--centred .aha-numbers__header{display:flex;flex-direction:column;align-items:center}
.aha-numbers--centred .aha-numbers__icon{margin-bottom:var(--aha-space-20)}
.aha-numbers--centred .aha-numbers__stats{grid-template-columns:repeat(4,minmax(0,1fr))}
@container aha-numbers (max-width:991px){
  .aha-numbers--centred .aha-numbers__stats{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@container aha-numbers (max-width:479px){
  .aha-numbers--centred .aha-numbers__stats{grid-template-columns:minmax(0,1fr)}
}
.aha-numbers--divided .aha-numbers__stats{grid-template-columns:repeat(3,minmax(0,1fr));gap:0;max-width:960px;margin:0 auto}
.aha-numbers--divided .aha-numbers__stat{align-items:center;text-align:center;padding:var(--aha-space-8) var(--aha-space-32)}
.aha-numbers--divided .aha-numbers__stat + .aha-numbers__stat{border-left:1px solid var(--aha-numbers-divider)}
@container aha-numbers (max-width:767px){
  .aha-numbers--divided .aha-numbers__stats{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-numbers--divided .aha-numbers__stat + .aha-numbers__stat{border-left:0;border-top:1px solid var(--aha-numbers-divider);padding-top:var(--aha-space-32)}
}

.aha-numbers--actions-icons .aha-numbers__layout{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:1fr auto auto 1fr;grid-template-areas:". stats" "header stats" "actions stats" ". stats";column-gap:var(--aha-space-64)}
.aha-numbers--actions-icons .aha-numbers__header{grid-area:header;margin:0}
.aha-numbers--actions-icons .aha-numbers__stats{grid-area:stats;align-self:center;grid-template-columns:repeat(2,minmax(0,1fr))}
.aha-numbers--actions-icons .aha-numbers__actions{grid-area:actions}
@container aha-numbers (max-width:991px){
  .aha-numbers--actions-icons .aha-numbers__layout{grid-template-columns:minmax(0,1fr);grid-template-rows:none;grid-template-areas:"header" "stats" "actions";row-gap:var(--aha-space-48)}
  .aha-numbers--actions-icons .aha-numbers__actions{margin-top:0}
}
@container aha-numbers (max-width:479px){
  .aha-numbers--actions-icons .aha-numbers__stats{grid-template-columns:minmax(0,1fr)}
}
